	// Handle N >= 1 separately to ensure we print at least one '1' if needed
	if n >= 1 {
		fmt.Println(a)
		a, b = b, a+b
	}

	// Loop through the rest of the Fibonacci sequence
	for b <= int64(n) && b > 0 {
		fmt.Println(b)
		a, b = b, a+b
	}
}

